-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Bastok_Markets_[S]/npcs/Loussaire.lua"]={["Path"]="scripts/zones/Bastok_Markets_[S]/npcs/Loussaire.lua",["SHA256"]="4206868723f926d7933e09e1a9dea5544443d0fa5f05d9dc9a70f0d03579bcce",["Text"]="-----------------------------------\n-- Area: Bastok Markets (S) (G-10)\n--  NPC: Loussaire\n-- !pos -248.677 -8.523 -125.734 87\n-----------------------------------\nlocal ID = zones[xi.zone.BASTOK_MARKETS_S]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n-- TODO: Reduce complexity\n-- Disable cyclomatic complexity check for this function:\n-- luacheck: ignore 561\nentity.onTrigger = function(player, npc)\n    local mLvl          = player:getMainLvl()\n    local mJob          = player:getMainJob()\n    local downwardHelix = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DOWNWARD_HELIX)\n\n    -- Controls the progress of each step. Everything will start at 1 and end at 4 (complete).\n    local loafersQuestProgress = player:getCharVar('AF_SCH_BOOTS')\n    local pantsQuestProgress   = player:getCharVar('AF_SCH_PANTS')\n    local gownQuestProgress    = player:getCharVar('AF_SCH_BODY')\n    local afProgress           = player:getCharVar('AF_Loussaire')\n\n    if player:getCharVar('AF_SCH_COMPLETE') == 0 then\n\n        -- They have a piece in progress.\n        if\n            afProgress > 0 and\n            (\n                loafersQuestProgress == 1 or\n                pantsQuestProgress == 1 or\n                gownQuestProgress == 1 or\n                loafersQuestProgress == 2 or\n                pantsQuestProgress == 2 or\n                gownQuestProgress == 2\n            )\n        then\n            local itemid   = xi.item.SCHOLARS_GOWN\n            local firstKI  = xi.keyItem.PEISTE_DUNG\n            local secondKI = xi.keyItem.SAMPLE_OF_GRAUBERG_CHERT\n\n            if loafersQuestProgress == 1 or loafersQuestProgress == 2 then\n                itemid   = xi.item.SCHOLARS_LOAFERS\n                firstKI  = xi.keyItem.RAFFLESIA_DREAMSPIT\n                secondKI = xi.keyItem.DROGAROGAN_BONEMEAL\n\n            elseif pantsQuestProgress == 1 or pantsQuestProgress == 2 then\n                itemid   = xi.item.SCHOLARS_PANTS\n                firstKI  = xi.keyItem.SLUG_MUCUS\n                secondKI = xi.keyItem.DJINN_EMBER\n            end\n\n            player:startEvent(50, itemid, firstKI, secondKI)\n\n        -- Nothing in progress and meet the starting requirements.\n        elseif\n            downwardHelix == xi.questStatus.QUEST_COMPLETED and\n            mJob == xi.job.SCH and\n            mLvl >= xi.settings.main.AF2_QUEST_LEVEL\n        then\n            -- If a player has completed any of the paths, it will be a different cutscene.\n            local counter = 0\n            if loafersQuestProgress == 4 then\n                counter = counter + 1\n            end\n\n            if pantsQuestProgress == 4 then\n                counter = counter + 1\n            end\n\n            if gownQuestProgress == 4 then\n                counter = counter + 1\n            end\n\n            -- Controls which CS to give the player based on completed paths.\n            local cutsceneID = 51\n            if counter == 1 then\n                cutsceneID = 52\n            elseif counter == 2 then\n                cutsceneID = 54\n            end\n\n            -- Check Key Items and give them their dynamic event.\n            if\n                player:hasKeyItem(xi.keyItem.RAFFLESIA_DREAMSPIT) and\n                player:hasKeyItem(xi.keyItem.DROGAROGAN_BONEMEAL) and\n                loafersQuestProgress == 3\n            then\n                -- Scholar's Loafers\n                player:startEvent(cutsceneID, 15748)\n                player:setLocalVar('item', 15748)\n                player:setLocalVar('firstKI', xi.keyItem.RAFFLESIA_DREAMSPIT)\n                player:setLocalVar('secondKI', xi.keyItem.DROGAROGAN_BONEMEAL)\n\n            elseif\n                player:hasKeyItem(xi.keyItem.SLUG_MUCUS) and\n                player:hasKeyItem(xi.keyItem.DJINN_EMBER) and\n                pantsQuestProgress == 3\n            then\n                -- Scholar's Pants\n                player:startEvent(cutsceneID, 16311)\n                player:setLocalVar('item', 16311)\n                player:setLocalVar('firstKI', xi.keyItem.SLUG_MUCUS)\n                player:setLocalVar('secondKI', xi.keyItem.DJINN_EMBER)\n\n            elseif\n                player:hasKeyItem(xi.keyItem.PEISTE_DUNG) and\n                player:hasKeyItem(xi.keyItem.SAMPLE_OF_GRAUBERG_CHERT) and\n                gownQuestProgress == 3\n            then\n                -- Scholar's Gown\n                player:startEvent(cutsceneID, 14580)\n                player:setLocalVar('item', 14580)\n                player:setLocalVar('firstKI', xi.keyItem.PEISTE_DUNG)\n                player:setLocalVar('secondKI', xi.keyItem.SAMPLE_OF_GRAUBERG_CHERT)\n\n            -- Show them the normal Menu to select from.\n            else\n                local params = 0 -- Controls which items to hide (Binary - 0XXX)\n\n                -- Scholar's Loafers\n                if loafersQuestProgress ~= 0 then\n                    params = 1\n                end\n\n                -- Scholar's Pants\n                if pantsQuestProgress ~= 0 then\n                    params = params + 2\n                end\n\n                -- Scholar's Gown\n                if gownQuestProgress ~= 0 then\n                    params = params + 4\n                end\n\n                if params < 8 then\n                    if afProgress > 0 then\n                        player:startEvent(53, params) -- Shorter CS than 49\n                    else\n                        player:startEvent(49, params)\n                    end\n                end\n            end\n\n        else\n            player:startEvent(48) -- Default message\n        end\n    end\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    if csid == 49 or csid == 53 then\n        -- Display Loafers\n        if option == 2 then\n            player:updateEvent(option, xi.keyItem.RAFFLESIA_DREAMSPIT, xi.keyItem.DROGAROGAN_BONEMEAL, 0, 0, 0, 0, 0)\n\n        -- Display Pants\n        elseif option == 4 then\n            player:updateEvent(option, xi.keyItem.SLUG_MUCUS, xi.keyItem.DJINN_EMBER, 0, 0, 0, 0, 0)\n\n        -- Display Gown\n        elseif option == 6 then\n            player:updateEvent(option, xi.keyItem.PEISTE_DUNG, xi.keyItem.SAMPLE_OF_GRAUBERG_CHERT, 0, 0, 0, 0, 0)\n\n        -- Confirm Loafers\n        elseif option == 1 then\n            player:setCharVar('AF_SCH_BOOTS', 1)\n\n        -- Confirm Pants\n        elseif option == 3 then\n            player:setCharVar('AF_SCH_PANTS', 1)\n\n        -- Confirm Gown\n        elseif option == 5 then\n            player:setCharVar('AF_SCH_BODY', 1)\n\n        elseif option > 7 then\n            player:printToPlayer('There was an error in the CS. Inform your Server Admin/GM.')\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 49 and option == 0 then\n        player:setCharVar('AF_Loussaire', 1)\n\n    elseif csid == 51 or csid == 52 or csid == 54 then\n        local itemid   = player:getLocalVar('item')\n        local firstKI  = player:getLocalVar('firstKI')\n        local secondKI = player:getLocalVar('secondKI')\n\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, itemid)\n\n        else\n            -- Remove LocalVars\n            player:setLocalVar('item', 0)\n            player:setLocalVar('firstKI', 0)\n            player:setLocalVar('secondKI', 0)\n\n            -- Flag the path complete\n            if itemid == 15748 then\n                player:setCharVar('AF_SCH_BOOTS', 4)\n            elseif itemid == 16311 then\n                player:setCharVar('AF_SCH_PANTS', 4)\n            else\n                player:setCharVar('AF_SCH_BODY', 4)\n            end\n\n            local afProgress = player:getCharVar('AF_Loussaire')\n            if afProgress == 3 then\n\n                -- They are done. Clean-up\n                player:setCharVar('AF_SCH_BOOTS',    0)\n                player:setCharVar('AF_SCH_PANTS',    0)\n                player:setCharVar('AF_SCH_BODY',     0)\n                player:setCharVar('AF_Loussaire',    0)\n                player:setCharVar('AF_SCH_COMPLETE', 1)\n\n            else\n                player:setCharVar('AF_Loussaire', afProgress + 1) -- They got an item. Add it!\n            end\n\n            player:delKeyItem(firstKI)\n            player:delKeyItem(secondKI)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, itemid)\n            player:addItem(itemid)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Caedarva_Mire/npcs/qm10.lua"]={["Path"]="scripts/zones/Caedarva_Mire/npcs/qm10.lua",["SHA256"]="66bba82cd66cc4680c37e4e6b5a360606035c591a75178e454d645e53c89e02c",["Text"]="-----------------------------------\n-- Area: Caedarva Mire\n--  NPC: qm10\n-- Involved in quest: Operation Teatime\n-- !pos 473 -31 75 79\n-----------------------------------\nlocal ID = zones[xi.zone.CAEDARVA_MIRE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local operationTeatime = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME)\n    local operationTeatimeProgress = player:getCharVar('OperationTeatimeProgress')\n\n    if\n        operationTeatime == xi.questStatus.QUEST_ACCEPTED and\n        operationTeatimeProgress == 3\n    then\n        player:startEvent(15)\n    else\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 15 then\n        npcUtil.completeQuest(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME, { item = 15602, var = 'OperationTeatimeProgress' })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Caedarva_Mire/npcs/qm9.lua"]={["Path"]="scripts/zones/Caedarva_Mire/npcs/qm9.lua",["SHA256"]="a0ddb76cbb3a42422c4e83a01e493379c15247330fc13fdb1789aeda72146a6e",["Text"]="-----------------------------------\n-- Area: Caedarva Mire\n--  NPC: qm9\n-- Involved in quest: The Wayward Automaton\n-- !pos  129 1.396 -631 79\n-----------------------------------\nlocal ID = zones[xi.zone.CAEDARVA_MIRE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local theWaywardAutomaton = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATON)\n    local theWaywardAutomatonProgress = player:getCharVar('TheWaywardAutomatonProgress')\n\n    if\n        theWaywardAutomaton == xi.questStatus.QUEST_ACCEPTED and\n        theWaywardAutomatonProgress == 2\n    then\n        if player:getCharVar('TheWaywardAutomatonNM') >= 1 then\n            player:startEvent(14)-- Event ID 14 for CS after toad\n        elseif not GetMobByID(ID.mob.CAEDARVA_TOAD):isSpawned() then\n            player:messageSpecial(ID.text.HIDEOUS_BEAST_EMERGES)\n            SpawnMob(ID.mob.CAEDARVA_TOAD):updateClaim(player) --Caedarva toad\n        end\n    else\n        player:messageSpecial(ID.text.SOMEONE_SLIPPED)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 14 then\n        player:setCharVar('TheWaywardAutomatonProgress', 3)\n        player:setCharVar('TheWaywardAutomatonNM', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Castle_Zvahl_Keep/npcs/_4i5.lua"]={["Path"]="scripts/zones/Castle_Zvahl_Keep/npcs/_4i5.lua",["SHA256"]="7e1ed1810ad4a75d393191d0c721208bd93fea7c914684c63ff92e2a4f725523",["Text"]="-----------------------------------\n-- Area: Castle Zvahl Keep\n--  NPC: Ore door\n-- Involved In Quest: Recollections\n-- !pos -14 0 69 162\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('recollectionsQuest') == 2\n    then\n        if\n            trade:hasItemQty(xi.item.WHINE_CELLAR_KEY, 1) and\n            trade:getItemCount() == 1\n        then\n            player:startEvent(8, xi.item.WHINE_CELLAR_KEY)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    player:startEvent(9)\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 8 then\n        player:tradeComplete()\n        player:setCharVar('recollectionsQuest', 3)\n        npcUtil.giveKeyItem(player, xi.keyItem.FOE_FINDER_MK_I)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Chateau_dOraguille/npcs/Curilla.lua"]={["Path"]="scripts/zones/Chateau_dOraguille/npcs/Curilla.lua",["SHA256"]="86dab8a6f344c67f88ebb179ba3fd3c1a2623ca77053370b955ce4cfa51cb157",["Text"]="-----------------------------------\n-- Area: Chateau d'Oraguille\n--  NPC: Curilla\n-- Starts and Finishes Quest: The General's Secret, Enveloped in Darkness, Peace for the Spirit,\n--                            Lure of the Wildcat (San d'Oria), Old Wounds\n-- !pos 27 0.1 0.1 233\n-----------------------------------\nlocal ID = zones[xi.zone.CHATEAU_DORAGUILLE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal sandyQuests = xi.quest.id.sandoria\n\nlocal trustMemory = function(player)\n    local memories = 0\n    -- 2 - PEACE_FOR_THE_SPIRIT\n    if player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT) then\n        memories = memories + 2\n    end\n\n    -- 4 - OLD_WOUNDS\n    if player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.OLD_WOUNDS) then\n        memories = memories + 4\n    end\n\n    -- 8 - THE_HEIR_TO_THE_LIGHT\n    if player:hasCompletedMission(xi.mission.log_id.SANDORIA, xi.mission.id.sandoria.THE_HEIR_TO_THE_LIGHT) then\n        memories = memories + 8\n    end\n\n    -- 16 - Heroine's Combat BCNM\n    -- if (playervar for Heroine's Combat) then\n    --  memories = memories + 16\n    -- end\n    -- 32 - FIT_FOR_A_PRINCE\n    if player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.FIT_FOR_A_PRINCE) then\n        memories = memories + 32\n    end\n\n    return memories\nend\n\nentity.onTrigger = function(player, npc)\n    local mLvl = player:getMainLvl()\n    local mJob = player:getMainJob()\n    local envelopedInDarkness = player:getQuestStatus(xi.questLog.SANDORIA, sandyQuests.ENVELOPED_IN_DARKNESS)\n    local peaceForTheSpirit = player:getQuestStatus(xi.questLog.SANDORIA, sandyQuests.PEACE_FOR_THE_SPIRIT)\n    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n\n    -- Trust: San d'Oria (Curilla)\n    if\n        player:hasKeyItem(xi.keyItem.SAN_DORIA_TRUST_PERMIT) and\n        not player:hasSpell(xi.magic.spell.CURILLA) and\n        player:getLocalVar('TrustDialogue') == 0\n    then\n        player:setLocalVar('TrustDialogue', 1)\n        player:startEvent(573, 0, 0, 0, trustMemory(player), 0, 0, 0, rank3)\n\n    -- \"Peace for the Spirit\" (RDM AF Body)\n    elseif peaceForTheSpirit == xi.questStatus.QUEST_ACCEPTED then\n        local questStatus = player:getCharVar('peaceForTheSpiritCS')\n        if questStatus == 5 then\n            player:startEvent(51)\n        elseif questStatus > 1 then\n            player:startEvent(113)\n        else\n            player:startEvent(108)\n        end\n    elseif\n        mJob == xi.job.RDM and\n        mLvl >= xi.settings.main.AF2_QUEST_LEVEL and\n        envelopedInDarkness == xi.questStatus.QUEST_COMPLETED and\n        peaceForTheSpirit == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(109) -- Start\n\n    -- Default dialogue after \"Peace for the Spirit\"\n    elseif peaceForTheSpirit == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(52)\n\n    -- Default dialogue after \"Enveloped in Darkness\"\n    elseif\n        envelopedInDarkness == xi.questStatus.QUEST_COMPLETED and\n        peaceForTheSpirit == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(114)\n\n    -- Default dialogue\n    else\n        player:startEvent(530)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 109 and option == 1 then\n        player:addQuest(xi.questLog.SANDORIA, sandyQuests.PEACE_FOR_THE_SPIRIT)\n    elseif csid == 573 and option == 2 then\n        player:addSpell(xi.magic.spell.CURILLA, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.CURILLA)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Chateau_dOraguille/npcs/Rahal.lua"]={["Path"]="scripts/zones/Chateau_dOraguille/npcs/Rahal.lua",["SHA256"]="b0daba88cf8e785d8374c39b6243ea9db44b1bd2d979c92a073d59b864a23f56",["Text"]="-----------------------------------\n-- Area: Chateau d'Oraguille\n--  NPC: Rahal\n-- Involved in Quests: The Holy Crest, Lure of the Wildcat (San d'Oria)\n-- !pos -28 0.1 -6 233\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local crestProgress = player:getCharVar('TheHolyCrest_Event')\n    local hasDragonCurseRemedy = player:hasKeyItem(xi.keyItem.DRAGON_CURSE_REMEDY)\n    local stalkerQuest = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER)\n    local stalkerProgress = player:getCharVar('KnightStalker_Progress')\n\n    -- Need to speak with Rahal to get Dragon Curse Remedy\n    if crestProgress == 5 and not hasDragonCurseRemedy then\n        player:startEvent(60) -- Gives key item\n    elseif crestProgress == 5 and hasDragonCurseRemedy then\n        player:startEvent(122) -- Reminder to go to Gelsba\n\n    -- Completed AF2, AF3 available, and currently on DRG.  No level check, since they cleared AF2.\n    elseif\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.CHASING_QUOTAS) == xi.questStatus.QUEST_COMPLETED and\n        stalkerQuest == xi.questStatus.QUEST_AVAILABLE and player:getMainJob() == xi.job.DRG\n    then\n        if player:getCharVar('KnightStalker_Declined') == 0 then\n            player:startEvent(121) -- Start AF3\n        else\n            player:startEvent(120) -- Short version if they previously declined\n        end\n    elseif stalkerQuest == xi.questStatus.QUEST_ACCEPTED then\n        if stalkerProgress == 0 then\n            player:startEvent(119) -- Reminder to go to Brugaire/Ceraulian\n        elseif player:hasKeyItem(xi.keyItem.CHALLENGE_TO_THE_ROYAL_KNIGHTS) then\n            if stalkerProgress == 1 then\n                player:startEvent(78) -- Reaction to challenge, go talk to Balasiel\n            elseif stalkerProgress == 2 then\n                player:startEvent(69) -- Reminder to talk to Balasiel\n            elseif stalkerProgress == 3 then\n                player:startEvent(110) -- To the south with you\n            end\n        end\n    elseif player:getCharVar('KnightStalker_Option2') == 1 then\n        player:startEvent(118) -- Optional CS after Knight Stalker\n\n    else\n        player:startEvent(529)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 60 then\n        npcUtil.giveKeyItem(player, xi.keyItem.DRAGON_CURSE_REMEDY)\n    elseif csid == 121 then\n        if option == 1 then\n            player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER)\n        else\n            player:setCharVar('KnightStalker_Declined', 1)\n        end\n    elseif csid == 120 and option == 1 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER)\n        player:setCharVar('KnightStalker_Declined', 0)\n    elseif csid == 78 then\n        player:setCharVar('KnightStalker_Progress', 2)\n    elseif csid == 110 then\n        player:setCharVar('KnightStalker_Progress', 4)\n    elseif csid == 118 then\n        player:setCharVar('KnightStalker_Option2', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Chateau_dOraguille/npcs/_6h0.lua"]={["Path"]="scripts/zones/Chateau_dOraguille/npcs/_6h0.lua",["SHA256"]="03a3392382027abfb2f221edd96da71cef205cf3a636afb70c662034da2245c8",["Text"]="-----------------------------------\n-- Area: Chateau d'Oraguille\n-- Door: Prince Royal's\n-- Finishes Quest: A Boy's Dream, Under Oath\n-- Involved in Missions: 3-1, 5-2, 8-2\n-- !pos -38 -3 73 233\n-----------------------------------\nlocal ID = zones[xi.zone.CHATEAU_DORAGUILLE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal function TrustMemory(player)\n    local memories = 0\n    -- 2 - LIGHTBRINGER\n    if player:hasCompletedMission(xi.mission.log_id.SANDORIA, xi.mission.id.sandoria.LIGHTBRINGER) then\n        memories = memories + 2\n    end\n\n    -- 4 - IMMORTAL_SENTRIES\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.IMMORTAL_SENTRIES) then\n        memories = memories + 4\n    end\n\n    -- 8 - UNDER_OATH\n    if player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH) then\n        memories = memories + 8\n    end\n\n    -- 16 - FIT_FOR_A_PRINCE\n    if player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.FIT_FOR_A_PRINCE) then\n        memories = memories + 16\n    end\n\n    -- 32 - Hero's Combat BCNM\n    -- if (playervar for Hero's Combat) then\n    --  memories = memories + 32\n    -- end\n    return memories\nend\n\nentity.onTrigger = function(player, npc)\n    local mLvl = player:getMainLvl()\n    local aBoysDream = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM)\n    local underOath = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH)\n\n    -- \"Under Oath\" (PLD AF Body)\n    if player:getCharVar('UnderOathCS') == 8 then\n        player:startEvent(89)\n    elseif\n        player:getMainJob() == xi.job.PLD and mLvl >= xi.settings.main.AF2_QUEST_LEVEL and\n        aBoysDream == xi.questStatus.QUEST_COMPLETED and underOath == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(90) -- Start\n\n    -- Trust: San d'Oria (Trion)\n    elseif\n        player:getRank(player:getNation()) >= 6 and\n        player:hasKeyItem(xi.keyItem.SAN_DORIA_TRUST_PERMIT) and\n        not player:hasSpell(xi.magic.spell.TRION)\n    then\n        player:startEvent(574, 0, 0, 0, TrustMemory(player))\n\n    -- \"A Boy's Dream\" (PLD AF Feet)\n    elseif player:getCharVar('aBoysDreamCS') == 8 then\n        player:startEvent(88)\n\n    -- San d'Oria Rank 10 (different default)\n    elseif\n        player:getNation() == xi.nation.SANDORIA and\n        player:getRank(player:getNation()) == 10\n    then\n        player:startEvent(62)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 88 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.GALLANT_LEGGINGS)\n        else\n            if player:getMainJob() == xi.job.PLD then\n                player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH)\n            end\n\n            player:delKeyItem(xi.keyItem.KNIGHTS_BOOTS)\n            player:addItem(xi.item.GALLANT_LEGGINGS)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.GALLANT_LEGGINGS) -- Gallant Leggings\n            player:setCharVar('aBoysDreamCS', 0)\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM)\n        end\n    elseif csid == 90 and option == 1 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH)\n        player:setCharVar('UnderOathCS', 0)\n    elseif csid == 89 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.GALLANT_SURCOAT)\n        else\n            player:addItem(xi.item.GALLANT_SURCOAT)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.GALLANT_SURCOAT) -- Gallant Surcoat\n            player:setCharVar('UnderOathCS', 9)\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:setTitle(xi.title.PARAGON_OF_PALADIN_EXCELLENCE)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH)\n        end\n    elseif csid == 574 and option == 2 then\n        player:addSpell(xi.magic.spell.TRION, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.TRION)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Chateau_dOraguille/npcs/_6h1.lua"]={["Path"]="scripts/zones/Chateau_dOraguille/npcs/_6h1.lua",["SHA256"]="7fd6e596aa4c17567e4915f0fad071fc9132f8ee29560c8ef2569615efc167ec",["Text"]="-----------------------------------\n-- Area: Chateau d'Oraguille\n-- Door: Prince Regent's Rm\n-- Starts and Finishes Quest: Prelude of Black and White (Start), Pieuje's Decision (Start)\n-- !pos -37 -3 31 233\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local sandyQuests = xi.quest.id.sandoria\n    local whmAf2 = player:getQuestStatus(xi.questLog.SANDORIA, sandyQuests.PRELUDE_OF_BLACK_AND_WHITE)\n    local whmAf3 = player:getQuestStatus(xi.questLog.SANDORIA, sandyQuests.PIEUJES_DECISION)\n\n    -- WHM AF quests\n    if\n        player:getMainJob() == xi.job.WHM and\n        player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n    then\n        if\n            whmAf2 == xi.questStatus.QUEST_COMPLETED and\n            whmAf3 == xi.questStatus.QUEST_AVAILABLE\n        then\n            player:startEvent(552) -- Start Quest \"Pieuje's Decision\"\n        end\n\n    -- San d'Oria Rank 10 (new default)\n    elseif\n        player:getNation() == xi.nation.SANDORIA and\n        player:getRank(player:getNation()) == 10\n    then\n        player:startEvent(73)\n\n    -- Default dialogue\n    else\n        player:startEvent(523)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 552 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Crawlers_Nest/npcs/Treasure_Chest.lua"]={["Path"]="scripts/zones/Crawlers_Nest/npcs/Treasure_Chest.lua",["SHA256"]="f5a7067d9a636a7339d3ba210a5de9eb9849363acec4073ffa5fac0da3943c4e",["Text"]="-----------------------------------\n-- Area: Crawler Nest\n--  NPC: Treasure Chest\n-- Involved In Quest: Enveloped in Darkness\n-- !zone 197\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        xi.quest.getVar(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS, 'Prog') >= 2 and\n        xi.quest.getVar(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS, 'Time') == 0 and\n        not player:hasKeyItem(xi.keyItem.CRAWLER_BLOOD)\n    then\n        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.CRAWLER_BLOOD)\n    else\n        local reward = xi.treasure.onTrade(player, npc, trade, 0, 0)\n\n        if reward > 0 then\n            xi.expeditionaryForce.onChestOpen(player)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    xi.treasure.onTrigger(player, npc)\nend\n\nreturn entity\n"},["scripts/zones/Crawlers_Nest/npcs/qm9.lua"]={["Path"]="scripts/zones/Crawlers_Nest/npcs/qm9.lua",["SHA256"]="1faa6f2a10eb475ecca191792436eac5f9914baa17d9b42cc15103b468c54a2f",["Text"]="-----------------------------------\n-- Area: Crawlers Nest\n--  NPC: ???\n-- Used In Quest: A Boy's Dream\n-- !pos -18 -8 124 197\n-----------------------------------\nlocal ID = zones[xi.zone.CRAWLERS_NEST]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM) == xi.questStatus.QUEST_ACCEPTED and\n        VanadielUniqueDay() ~= player:getCharVar('DreadbugNM_Day')\n    then\n        if\n            GetSystemTime() > player:getCharVar('DreadbugNM_Timer') + 30 and\n            npcUtil.popFromQM(player, npc, ID.mob.DREADBUG, { claim = true, hide = 0 })\n        then\n            player:messageSpecial(ID.text.SENSE_OF_FOREBODING)\n            player:setCharVar('DreadbugNM_Timer', GetSystemTime() + 180)\n            player:setCharVar('DreadbugNM_Day', VanadielUniqueDay())\n        else\n            player:messageSpecial(ID.text.NOTHING_SEEMS_TO_HAPPEN)\n        end\n    else\n        player:messageSpecial(ID.text.NOTHING_WILL_HAPPEN_YET)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Crawlers_Nest_[S]/npcs/Rodeupansat.lua"]={["Path"]="scripts/zones/Crawlers_Nest_[S]/npcs/Rodeupansat.lua",["SHA256"]="7eba05d17d08d5f27aba94933bae394c9ad92714ad073d9132d4b57f0f22a564",["Text"]="-----------------------------------\n-- Area: Crawlers_Nest_[S]\n--  NPC: Rodeupansat\n-- Starts and Finishes Quest: EVIL_AT_THE_INLET\n-- !pos 129 -34 26 171\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local evilAtTheInlet = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.EVIL_AT_THE_INLET)\n\n    -- Change to BRASS_RIBBON_OF_SERVICE later when Campaign has been added.\n    if\n        evilAtTheInlet == xi.questStatus.QUEST_AVAILABLE and\n        player:hasKeyItem(xi.keyItem.BRONZE_RIBBON_OF_SERVICE) and\n        player:getMainLvl() >= 30\n    then\n        player:startEvent(107) -- Start quest \"Evil at the Inlet\"\n    elseif evilAtTheInlet == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.EVIL_WARDING_SEAL) then\n            player:startEvent(108) -- During quest after receiving KI and before losing KI\n        else\n            player:startEvent(109) -- After losing KI and returning for reward\n        end\n    elseif evilAtTheInlet == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(110) -- New standard dialog after \"Evil at the Inlet\"\n    else\n        player:startEvent(106) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 107 then\n        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.EVIL_AT_THE_INLET)\n        npcUtil.giveKeyItem(player, xi.keyItem.EVIL_WARDING_SEAL)\n    elseif csid == 109 then\n        npcUtil.completeQuest(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.EVIL_AT_THE_INLET, { item = xi.item.SCROLL_OF_RECALL_JUGNER })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Davoi/npcs/qm1.lua"]={["Path"]="scripts/zones/Davoi/npcs/qm1.lua",["SHA256"]="3c293af7fac733e223e47f7ae10aedf07ebf9ad340b63379ab2d6f77b48e907a",["Text"]="-----------------------------------\n-- Area: Davoi\n--  NPC: ??? (qm1)\n-- Involved in Quest: To Cure a Cough\n-- !pos -115.830 -0.427 -184.289 149\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH) == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.THYME_MOSS)\n    then\n        npcUtil.giveKeyItem(player, xi.keyItem.THYME_MOSS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Eastern_Adoulin/npcs/Octavien.lua"]={["Path"]="scripts/zones/Eastern_Adoulin/npcs/Octavien.lua",["SHA256"]="53949b05184f3bf1de539f15e648effc89a556f6e510233ea6e7b9167502ffcb",["Text"]="-----------------------------------\n-- Area: Eastern Adoulin (257)\n--  NPC: Octavien\n-- Type: Palace Guard\n-- Starts Children of the Rune\n-- !pos 100.580 -40.150 -63.830\n-----------------------------------\nlocal ID = zones[xi.zone.EASTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n-- Various quest states for Children Of The Rune (COTR).\n-- Corresponds to possible values for the char var 'RUN_COTR'.\nlocal cotrStates =\n{\n    -- Player triggered the quest but declined to accept the quest in the\n    -- dialog options. On next trigger jump to the quest continuation cutscene.\n    TRIGGERED = 1,\n    -- Player has not yet finished the rune enhacement phase of the quest.\n    -- On next trigger, jump straight to the rune enhancement cutscene.\n    RUNE_ENHANCEMENT = 2,\n    -- Player would have completed the quest, but had a full inventory. On\n    -- next interaction, jump to the final cutscene and try to issue the reward.\n    REWARD_PENDING = 3\n}\n\nentity.onTrigger = function(player, npc)\n    -- CHILDREN OF THE RUNE\n    local cotrQuestStatus = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.CHILDREN_OF_THE_RUNE)\n    -- NOTE: The if-statements are ordered in reverse order from when they occur\n    -- for natural fallthrough, to avoid needing `not` statements in them.\n    if cotrQuestStatus == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(28)\n    elseif player:getCharVar('RUN_COTR') == cotrStates.REWARD_PENDING then\n        player:startEvent(29)\n    elseif player:getCharVar('RUN_COTR') == cotrStates.RUNE_ENHANCEMENT then\n        player:startEvent(26, 1)\n    elseif\n        cotrQuestStatus == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.YAHSE_WILDFLOWER_PETAL)\n    then\n        player:startEvent(26)\n    elseif cotrQuestStatus == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(25)\n    elseif player:getCharVar('RUN_COTR') == cotrStates.TRIGGERED then\n        player:startEvent(24)\n    elseif\n        cotrQuestStatus == xi.questStatus.QUEST_AVAILABLE and\n        player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n    then\n        player:startEvent(23)\n    else\n        player:startEvent(27) -- Standard dialog\n    end\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    if csid == 26 then\n        if option == 1 then\n            -- Half the players MP and HP unless the HP is really low, to avoid\n            -- killing the player.\n            local hp = player:getHP()\n            if hp > 5 then\n                player:setHP(math.ceil(hp / 2))\n            end\n\n            local mp = player:getMP()\n            if mp > 5 then\n                player:setMP(math.ceil(mp / 2))\n            end\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- CHILDREN OF THE RUNE\n    if csid == 23 or csid == 24 then\n        if option == 0 then\n            player:setCharVar('RUN_COTR', cotrStates.TRIGGERED)\n        elseif option == 1 then\n            player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.CHILDREN_OF_THE_RUNE)\n        end\n    elseif csid == 26 then\n        if option == 0 then\n            player:setCharVar('RUN_COTR', cotrStates.RUNE_ENHANCEMENT)\n        elseif option == 1 then\n            player:setCharVar('RUN_COTR', cotrStates.REWARD_PENDING)\n        end\n    end\n\n    -- Attempt to issue the Children of the Rune reward if the player has space.\n    if player:getCharVar('RUN_COTR') == cotrStates.REWARD_PENDING then\n        if npcUtil.giveItem(player, xi.item.SOWILO_CLAYMORE) then  -- Sowilo Claymore\n            player:unlockJob(xi.job.RUN)\n            player:messageSpecial(ID.text.YOU_CAN_NOW_BECOME, 1)  -- You can now become a rune fencer!\n            npcUtil.giveKeyItem(player, xi.keyItem.JOB_GESTURE_RUNE_FENCER)\n            player:setCharVar('RUN_COTR', 0)\n            player:delKeyItem(xi.keyItem.YAHSE_WILDFLOWER_PETAL)\n            player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.CHILDREN_OF_THE_RUNE)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/FeiYin/npcs/Dry_Fountain.lua"]={["Path"]="scripts/zones/FeiYin/npcs/Dry_Fountain.lua",["SHA256"]="6c54791a39f4d73f20f819ecc39615c9f82c39614ab8ef7c738bb9fedc3f14c9",["Text"]="-----------------------------------\n-- Area: FeiYin\n--  NPC: Dry Fountain\n-- Involved In Quest: Peace for the Spirit\n-- !pos -17 -16 71 204\n-----------------------------------\nlocal ID = zones[xi.zone.FEIYIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT) == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.ANTIQUE_COIN, 1) and\n            trade:getItemCount() == 1\n        then\n            player:startEvent(17)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    player:messageSpecial(ID.text.DRIED_UP_FOUNTAIN)\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 17 then\n        player:tradeComplete()\n        player:setCharVar('peaceForTheSpiritCS', 2)\n    end\nend\n\nreturn entity\n"},["scripts/zones/FeiYin/npcs/Treasure_Chest.lua"]={["Path"]="scripts/zones/FeiYin/npcs/Treasure_Chest.lua",["SHA256"]="fbb93f5fb772d141927963fc054c3aa010aed0b7e4225f694a9705ca09756314",["Text"]="-----------------------------------\n-- Area: Fei'Yin\n--  NPC: Treasure Chest\n-- !zone 204\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SORCERY_OF_THE_NORTH) == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.FEIYIN_MAGIC_TOME)\n    then\n        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.FEIYIN_MAGIC_TOME)\n    else\n        local reward = xi.treasure.onTrade(player, npc, trade, 0, 0)\n\n        if reward > 0 then\n            xi.expeditionaryForce.onChestOpen(player)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    xi.treasure.onTrigger(player, npc)\nend\n\nreturn entity\n"},["scripts/zones/FeiYin/npcs/qm1.lua"]={["Path"]="scripts/zones/FeiYin/npcs/qm1.lua",["SHA256"]="c37a751488d3ae8390ded39d074b707239a34d1773a58680fc9d15833e6d849e",["Text"]="-----------------------------------\n-- Area: FeiYin\n--  NPC: qm1 (???)\n-- Involved In Quest: Pieuje's Decision\n-- !pos -55 -16 69 204\n-----------------------------------\nlocal ID = zones[xi.zone.FEIYIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.TAVNAZIA_BELL) and\n        not player:hasItem(xi.item.TAVNAZIAN_MASK) and\n        not GetMobByID(ID.mob.ALTEDOUR_I_TAVNAZIA):isSpawned()\n    then\n        player:confirmTrade()\n        player:messageSpecial(ID.text.EVIL_PRESENCE)\n        SpawnMob(ID.mob.ALTEDOUR_I_TAVNAZIA):updateClaim(player)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION) == xi.questStatus.QUEST_ACCEPTED then\n        player:messageSpecial(ID.text.SOUL_OF_TAVNAZIA)\n    else\n        player:messageSpecial(ID.text.YOU_FIND_NOTHING)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Fort_Karugo-Narugo_[S]/npcs/Pecca-Pocca.lua"]={["Path"]="scripts/zones/Fort_Karugo-Narugo_[S]/npcs/Pecca-Pocca.lua",["SHA256"]="6298316e58ed85f0997aa0f27a70d44b11fb1761fd6b0bc84c16d79d30e61f98",["Text"]="-----------------------------------\n-- Area: Fort_Karugo-Narugo_[S]\n--  NPC: Pecca-Pocca\n-- Involved In Quest: REQUIEM_FOR_THE_DEPARTED\n-- !pos -163 -68 -155 96\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REQUIEM_FOR_THE_DEPARTED) == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.SHEAF_OF_HANDMADE_INCENSE) then\n            player:startEvent(233) -- standard dialogue after receiving KI\n        else\n            player:startEvent(234) -- to receive KI\n        end\n    else\n        player:startEvent(233)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 234 then\n        npcUtil.giveKeyItem(player, xi.keyItem.SHEAF_OF_HANDMADE_INCENSE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Garlaige_Citadel/npcs/Mashira.lua"]={["Path"]="scripts/zones/Garlaige_Citadel/npcs/Mashira.lua",["SHA256"]="bf7b41b32a9b90de0ba8279c4b8c3a0e1b9db9bbc70ced55db7224aff0881437",["Text"]="-----------------------------------\n-- Area: Garlaige Citadel\n--  NPC: Mashira\n-- Involved in Quests: Rubbish day, Making Amens!\n-- !pos 141 -6 138 200\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS) == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.BROKEN_WAND) then\n            player:startEvent(11, 3)\n        else player:startEvent(11, 0) -- Making Amens dialogue\n        end\n    else\n        player:startEvent(11, 3) -- Standard dialog and menu\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        csid == 11 and\n        option == 0 and\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS) == xi.questStatus.QUEST_ACCEPTED\n    then\n        npcUtil.giveKeyItem(player, xi.keyItem.BROKEN_WAND)\n        player:tradeComplete()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Garlaige_Citadel/npcs/Oaken_Box.lua"]={["Path"]="scripts/zones/Garlaige_Citadel/npcs/Oaken_Box.lua",["SHA256"]="09a40e7da4cdba59bc553d0fc4671a056428dc00184c475ba63afd25e262f49a",["Text"]="-----------------------------------\n-- Area: Garlaige Citadel\n--  NPC: Oaken Box\n-- Involved In Quest: Peace for the Spirit\n-- !pos -164 0.1 225 200\n-----------------------------------\nlocal ID = zones[xi.zone.GARLAIGE_CITADEL]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.NAIL_PULLER)\n    then\n        player:startEvent(14)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if GetMobByID(ID.mob.GUARDIAN_STATUE):isAlive() then\n        player:messageSpecial(ID.text.FEELS_WRONG)\n    elseif\n        player:hasItem(xi.item.NAIL_PULLER) and\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT) == xi.questStatus.QUEST_ACCEPTED\n    then\n        player:messageSpecial(ID.text.BOXES_SCATTERED, xi.item.NAIL_PULLER)\n    elseif\n        player:getCharVar('peaceForTheSpiritCS') == 4 and\n        not player:hasItem(xi.item.NAIL_PULLER) and\n        not GetMobByID(ID.mob.GUARDIAN_STATUE):isSpawned()\n    then\n        SpawnMob(ID.mob.GUARDIAN_STATUE):updateClaim(player)\n    else\n        player:messageSpecial(ID.text.BOXES_HERE)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 14 then\n        player:confirmTrade()\n        player:setCharVar('peaceForTheSpiritCS', 5)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Giddeus/npcs/Altar_of_Offerings.lua"]={["Path"]="scripts/zones/Giddeus/npcs/Altar_of_Offerings.lua",["SHA256"]="a7d0e2c0ead1f74ff1e03db01acdb2f80b3bd9372a739206e47f4fac9148fee7",["Text"]="-----------------------------------\n-- Area: Giddeus\n--  NPC: Alter of Offerings\n-- Involved in Quest: A Crisis in the Making\n-- !pos -137 17 177 145\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local crisisstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_CRISIS_IN_THE_MAKING)\n    if crisisstatus >= 1 and player:getCharVar('QuestCrisisMaking_var') == 1 then\n        player:startEvent(53) -- A Crisis in the Making: Receive Offering\n    else\n        player:startEvent(60) -- Standard Message\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 53 and option == 1 then\n        npcUtil.giveKeyItem(player, xi.keyItem.OFF_OFFERING)\n        player:setCharVar('QuestCrisisMaking_var', 2)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Gusgen_Mines/npcs/qm3.lua"]={["Path"]="scripts/zones/Gusgen_Mines/npcs/qm3.lua",["SHA256"]="ca4a1722019a19d2e2e59146d3d1618b02cd038af42ac158843be25a8e09e553",["Text"]="-----------------------------------\n-- Area: Gusgen Mines\n--  NPC: qm3 (???)\n-- Involved In Quest: Healing the Land\n-- !pos -168 1 311 196\n-----------------------------------\nlocal ID = zones[xi.zone.GUSGEN_MINES]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local healingTheLand = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.HEALING_THE_LAND)\n\n    if\n        healingTheLand == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.SEAL_OF_BANISHING)\n    then\n        player:delKeyItem(xi.keyItem.SEAL_OF_BANISHING)\n        player:messageSpecial(ID.text.FOUND_LOCATION_SEAL, xi.keyItem.SEAL_OF_BANISHING)\n    elseif\n        healingTheLand == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.SEAL_OF_BANISHING)\n    then\n        player:messageSpecial(ID.text.IS_ON_THIS_SEAL, xi.keyItem.SEAL_OF_BANISHING)\n    else\n        player:messageSpecial(ID.text.LETTERS_IS_WRITTEN_HERE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Heavens_Tower/npcs/Chumimi.lua"]={["Path"]="scripts/zones/Heavens_Tower/npcs/Chumimi.lua",["SHA256"]="bbf7e6e3cbdee8f0748b8cd0274a4a9d100dbe803ba40afb3a3e6c76a183affe",["Text"]="-----------------------------------\n-- Area: Heaven's Tower\n--  NPC: Chumimi\n-- Starts and Finishes Quest: The Three Magi, Recollections\n-- !pos 0.1 30 21 242\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI) == xi.questStatus.QUEST_ACCEPTED and\n        trade:hasItemQty(xi.item.GLOWSTONE, 1) and\n        trade:getItemCount() == 1\n    then\n        player:startEvent(269) -- Finish Quest \"The Three Magi\"\n    elseif\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('recollectionsQuest') < 2 and\n        trade:hasItemQty(xi.item.BAG_OF_SEEDS, 1) and\n        trade:getItemCount() == 1\n    then\n        player:startEvent(271, 0, 520)\n    elseif\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('rootProblem') == 1 and\n        trade:hasItemQty(xi.item.SQUARE_OF_SILK_CLOTH, 1) and\n        trade:getItemCount() == 1\n    then\n        player:startEvent(278)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local theThreeMagi = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI)\n    local recollections = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS)\n    local rootProblem = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM)\n    local mLvl = player:getMainLvl()\n    local mJob = player:getMainJob()\n\n    if\n        theThreeMagi == xi.questStatus.QUEST_AVAILABLE and\n        mJob == xi.job.BLM and\n        mLvl >= xi.settings.main.AF1_QUEST_LEVEL\n    then\n        player:startEvent(260, 0, 613, 0, 0, xi.item.METEORITE, xi.item.GLOWSTONE) -- Start Quest \"The Three Magi\"\n    elseif theThreeMagi == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(261, 0, 0, 0, 0, xi.item.METEORITE, xi.item.GLOWSTONE) -- During Quest \"The Three Magi\"\n    elseif\n        theThreeMagi == xi.questStatus.QUEST_COMPLETED and\n        recollections == xi.questStatus.QUEST_AVAILABLE and\n        (mJob == xi.job.BLM and mLvl < xi.settings.main.AF2_QUEST_LEVEL or mJob ~= xi.job.BLM)\n    then\n        player:startEvent(268) -- New standard dialog after \"The Three Magi\"\n    elseif\n        theThreeMagi == xi.questStatus.QUEST_COMPLETED and\n        mJob == xi.job.BLM and\n        mLvl >= xi.settings.main.AF2_QUEST_LEVEL and\n        not player:needToZone() and\n        recollections == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(270, 0, xi.item.BAG_OF_SEEDS) -- Start Quest \"Recollections\"\n    elseif\n        recollections == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.FOE_FINDER_MK_I)\n    then\n        player:startEvent(275) -- Finish Quest \"Recollections\"\n    elseif\n        recollections == xi.questStatus.QUEST_COMPLETED and\n        rootProblem == xi.questStatus.QUEST_AVAILABLE and\n        mJob == xi.job.BLM and\n        mLvl >= 50 and\n        not player:needToZone()\n    then\n        player:startEvent(276, 0, xi.item.SQUARE_OF_SILK_CLOTH) -- Start Quest \"The Root of The problem\"\n    elseif rootProblem == xi.questStatus.QUEST_ACCEPTED then\n        local rootProblemCS = player:getCharVar('rootProblem')\n\n        if rootProblemCS == 1 then\n            player:startEvent(277, 0, xi.item.SQUARE_OF_SILK_CLOTH)\n        elseif rootProblemCS == 2 then\n            player:startEvent(279)\n        elseif rootProblemCS == 3 then\n            player:startEvent(281)\n        end\n    else\n        player:startEvent(259) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 260 then\n        -- option 3: Koru-Moru -- option 2: Shantotto -- option 1: Yoran-Oran\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI)\n        player:setCharVar('theThreeMagiSupport', option)\n    elseif csid == 269 then\n        if npcUtil.giveItem(player, xi.item.CASTING_WAND) then\n            local choosetitle = player:getCharVar('theThreeMagiSupport')\n\n            if choosetitle == 3 then\n                player:addTitle(xi.title.PROFESSOR_KORU_MORU_SUPPORTER)\n            elseif choosetitle == 2 then\n                player:addTitle(xi.title.DOCTOR_SHANTOTTO_SUPPORTER)\n            else\n                player:addTitle(xi.title.DOCTOR_YORAN_ORAN_SUPPORTER)\n            end\n\n            player:tradeComplete()\n            player:needToZone(true)\n            player:setCharVar('theThreeMagiSupport', 0)\n            player:addFame(xi.fameArea.WINDURST, 20)\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI)\n        end\n    elseif csid == 270 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS)\n    elseif csid == 271 then\n        player:tradeComplete()\n        player:setCharVar('recollectionsQuest', 2)\n    elseif csid == 275 then\n        if npcUtil.giveItem(player, xi.item.WIZARDS_SABOTS) then\n            player:setCharVar('recollectionsQuest', 0)\n            player:delKeyItem(xi.keyItem.FOE_FINDER_MK_I)\n            player:addFame(xi.fameArea.WINDURST, 20)\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS)\n        end\n    elseif csid == 276 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM)\n        player:setCharVar('rootProblem', 1)\n    elseif csid == 279 then\n        npcUtil.giveKeyItem(player, xi.keyItem.SLUICE_SURVEYOR_MK_I)\n    elseif csid == 281 then\n        if npcUtil.giveItem(player, xi.item.WIZARDS_PETASOS) then\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM)\n            player:addFame(xi.fameArea.WINDURST, 20)\n            player:addTitle(xi.title.PARAGON_OF_BLACK_MAGE_EXCELLENCE)\n            player:delKeyItem(xi.keyItem.SLUICE_SURVEYOR_MK_I)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Heavens_Tower/npcs/Kupipi.lua"]={["Path"]="scripts/zones/Heavens_Tower/npcs/Kupipi.lua",["SHA256"]="d90a0d749ab67aa798178c2eb3ad71c805653b294e4c1822919073f956407246",["Text"]="-----------------------------------\n-- Area: Heaven's Tower\n--  NPC: Kupipi\n-- Involved in Mission 2-3\n-- Involved in Quest: Riding on the Clouds\n-- !pos 2 0.1 30 242\n-----------------------------------\nlocal ID = zones[xi.zone.HEAVENS_TOWER]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal trustMemory = function(player)\n    local memories = 0\n    if player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.THE_THREE_KINGDOMS) then\n        memories = memories + 2\n    end\n\n    -- 4 - nothing\n    if player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.MOON_READING) then\n        memories = memories + 8\n    end\n\n    -- 16 - chocobo racing\n    --  memories = memories + 16\n    return memories\nend\n\nentity.onTrigger = function(player, npc)\n    local trustSandoria = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n    local trustBastok   = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TRUST_BASTOK)\n    local trustWindurst = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n    local windurstFirstTrust = player:getCharVar('WindurstFirstTrust')\n    local kupipiTrustChatFlag = player:getLocalVar('KupipiTrustChatFlag')\n    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n\n    if\n        trustWindurst == xi.questStatus.QUEST_ACCEPTED and\n        (trustSandoria == xi.questStatus.QUEST_COMPLETED or trustBastok == xi.questStatus.QUEST_COMPLETED)\n    then\n        player:startEvent(439, 0, 0, 0, trustMemory(player), 0, 0, 0, rank3)\n    elseif\n        trustWindurst == xi.questStatus.QUEST_ACCEPTED and\n        windurstFirstTrust == 0\n    then\n        player:startEvent(435, 0, 0, 0, trustMemory(player), 0, 0, 0, rank3)\n    elseif\n        trustWindurst == xi.questStatus.QUEST_ACCEPTED and\n        windurstFirstTrust == 1 and\n        kupipiTrustChatFlag == 0\n    then\n        player:startEvent(436)\n        player:setLocalVar('KupipiTrustChatFlag', 1)\n    elseif\n        trustWindurst == xi.questStatus.QUEST_ACCEPTED and\n        windurstFirstTrust == 2\n    then\n        player:startEvent(437)\n    elseif\n        trustWindurst == xi.questStatus.QUEST_COMPLETED and\n        not player:hasSpell(xi.magic.spell.NANAA_MIHGO) and\n        kupipiTrustChatFlag == 0\n    then\n        player:startEvent(438)\n        player:setLocalVar('KupipiTrustChatFlag', 1)\n    elseif player:getNation() == xi.nation.WINDURST then\n        if player:getRank(player:getNation()) == 10 then\n            player:startEvent(408) -- After achieving Windurst Rank 10, Kupipi has more to say\n        else\n            player:startEvent(251)\n        end\n    else\n        player:startEvent(251)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    --TRUST\n    if csid == 435 then\n        player:addSpell(xi.magic.spell.KUPIPI, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.KUPIPI)\n        player:setCharVar('WindurstFirstTrust', 1)\n    elseif csid == 437 then\n        player:delKeyItem(xi.keyItem.GREEN_INSTITUTE_CARD)\n        player:messageSpecial(ID.text.KEYITEM_LOST, xi.keyItem.GREEN_INSTITUTE_CARD)\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST, {\n            keyItem = xi.keyItem.WINDURST_TRUST_PERMIT,\n            title = xi.title.THE_TRUSTWORTHY,\n            var = 'WindurstFirstTrust' })\n        player:messageSpecial(ID.text.CALL_MULTIPLE_ALTER_EGO)\n    elseif csid == 439 then\n        player:addSpell(xi.magic.spell.KUPIPI, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.KUPIPI)\n        player:delKeyItem(xi.keyItem.GREEN_INSTITUTE_CARD)\n        player:messageSpecial(ID.text.KEYITEM_LOST, xi.keyItem.GREEN_INSTITUTE_CARD)\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST, {\n            keyItem = xi.keyItem.WINDURST_TRUST_PERMIT })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Ifrits_Cauldron/npcs/Altar_of_Ashes.lua"]={["Path"]="scripts/zones/Ifrits_Cauldron/npcs/Altar_of_Ashes.lua",["SHA256"]="a084c4a3a1773ca4a3cd80ce61c226ba6b71ece5e7ae99f2aaad1bb72e362280",["Text"]="-----------------------------------\n-- Area: Ifrit's Cauldron\n--  NPC: Altar of Ashes\n-- Involved in Quest: Greetings to the Guardian\n-- !pos 16 .1 -58 205\n-----------------------------------\nlocal ID = zones[xi.zone.IFRITS_CAULDRON]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local guardian = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.GREETINGS_TO_THE_GUARDIAN)\n\n    if\n        guardian == xi.questStatus.QUEST_ACCEPTED and\n        trade:hasItemQty(xi.item.BUNCH_OF_WILD_PAMAMAS, 1)\n    then\n        player:messageSpecial(ID.text.ALTAR_OFFERING, 0, xi.item.BUNCH_OF_WILD_PAMAMAS)\n        player:setCharVar('PamamaVar', 1) -- Set variable to reflect first completion of quest\n        player:tradeComplete()\n    elseif\n        guardian == xi.questStatus.QUEST_COMPLETED and\n        trade:hasItemQty(xi.item.BUNCH_OF_WILD_PAMAMAS, 1)\n    then\n        player:messageSpecial(ID.text.ALTAR_OFFERING, 0, xi.item.BUNCH_OF_WILD_PAMAMAS)\n        player:setCharVar('PamamaVar', 2) -- Set variable to reflect repeat of quest, not first time\n        player:tradeComplete()\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local guardian = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.GREETINGS_TO_THE_GUARDIAN)\n\n    if\n        guardian == xi.questStatus.QUEST_ACCEPTED and\n        (player:getCharVar('PamamaVar') == 1 or player:getCharVar('PamamaVar') == 2)\n    then\n        player:messageSpecial(ID.text.ALTAR_COMPLETED)\n    elseif\n        guardian == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('PamamaVar') == 0\n    then\n        player:messageSpecial(ID.text.ALTAR_INSPECT)\n    else\n        player:messageSpecial(ID.text.ALTAR_STANDARD)\n    end\nend\n\nreturn entity\n"}};
